// 1. Primary Class Template
template <typename T>
struct Info {
    T value;
    static constexpr bool is_ptr = false;
};

// 2. Full Specialization (for type bool)
template <>
struct Info<bool> {
    bool b; // Custom storage
    void flip() { b = !b; }
    static constexpr bool is_ptr = false;
};

// 3. Partial Specialization (for all pointer types T*)
template <typename T>
struct Info<T*> {
    T* ptr; // Specific member
    T& deref() { return *ptr; }
    static constexpr bool is_ptr = true;
};

// 4. Type Deduction in action
Info<int> I1;
auto deduced_type_I1 = I1;       // auto -> Info<int>
Info<char*> I2;
decltype(I2) inferred_type_I2;   // decltype -> Info<char*>
auto check = I2.is_ptr;          // auto -> const bool (true)
